// Signs release builds with the Google Play upload key when this computer has it.
//
// The key and its password never go in the repo: they are read from Gradle
// properties (HS_UPLOAD_STORE_FILE, HS_UPLOAD_KEY_ALIAS, HS_UPLOAD_STORE_PASSWORD,
// HS_UPLOAD_KEY_PASSWORD) in the user's ~/.gradle/gradle.properties. Without them,
// release builds fall back to the debug key, fine for a test APK but not for Play.
// The android/ folder is generated by `expo prebuild`, so this runs on every prebuild.
const { withAppBuildGradle } = require('expo/config-plugins');

const RELEASE_CONFIG = `
        release {
            if (project.hasProperty('HS_UPLOAD_STORE_FILE')) {
                storeFile file(HS_UPLOAD_STORE_FILE)
                storePassword HS_UPLOAD_STORE_PASSWORD
                keyAlias HS_UPLOAD_KEY_ALIAS
                keyPassword HS_UPLOAD_KEY_PASSWORD
            }
        }`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents;
    if (gradle.includes('HS_UPLOAD_STORE_FILE')) return cfg;

    const debugBlock = /(signingConfigs \{\s*debug \{[^}]*\})/;
    const releaseUsesDebug =
      /(release \{\s*(?:\/\/[^\n]*\n\s*)*)signingConfig signingConfigs\.debug/;
    if (!debugBlock.test(gradle) || !releaseUsesDebug.test(gradle)) {
      throw new Error('withReleaseSigning: android/app/build.gradle has an unexpected layout');
    }
    gradle = gradle.replace(debugBlock, `$1${RELEASE_CONFIG}`);
    gradle = gradle.replace(
      releaseUsesDebug,
      "$1signingConfig project.hasProperty('HS_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug",
    );
    cfg.modResults.contents = gradle;
    return cfg;
  });
};
